    pub fn mode(id: u32) -> Option<yoake_slice::bridge::Mode> {
        if BRIDGED.binary_search(&id).is_err() {
            return None;
        }
        if OBSERVE_ONLY.binary_search(&id).is_ok() {
            Some(yoake_slice::bridge::Mode::ObserveOnly)
        } else {
            Some(yoake_slice::bridge::Mode::Full)
        }
    }

